INSERT INTO research_companies (ticker,name,sector,exchange,market_cap,memberships_json,index_weights_json) VALUES ('NVDA','NVIDIA CORP','Information Technology','NASDAQ',4719968000000,'["S&P 500","Russell 3000","Nasdaq-100 (QQQ)"]','{"S&P 500":7.45,"Russell 3000":6.69,"Nasdaq-100 (QQQ)":0}') ON CONFLICT(ticker) DO UPDATE SET name=excluded.name,sector=excluded.sector,exchange=excluded.exchange,market_cap=excluded.market_cap,memberships_json=excluded.memberships_json,index_weights_json=excluded.index_weights_json,updated_at=CURRENT_TIMESTAMP;
INSERT INTO company_dossiers (ticker,status,description,lede,sells,revenue_model,opportunity,must_go_right,editor_note,bull_title,bull_json,bear_title,bear_json,thesis_breaker,financial_drivers_json,risks_json,monitor_json,questions_json,competitors,evidence_date,validated_at,published_at,updated_at) VALUES ('NVDA','published','Accelerated computing platforms spanning chips, systems, networking, and software.','NVIDIA has evolved from a graphics-chip company into a full-stack accelerated-computing platform central to modern AI infrastructure.','GPUs, networking, systems, software, and platform services for data center, gaming, visualization, automotive, and edge markets.','Semiconductor and system sales, networking, software licensing, support, and cloud-access services.','AI training and inference are increasing demand for accelerated computing, while CUDA and system-level integration strengthen adoption.','Customers must continue earning value from AI infrastructure and NVIDIA must maintain performance, supply, and ecosystem leadership.','The debate is no longer whether AI compute demand exists; it is how durable NVIDIA’s share and returns remain as customers, competitors, and custom silicon mature.','The full-stack standard for accelerated computing','["CUDA and developer adoption create a powerful software ecosystem.","Chips, networking, systems, and software are co-designed.","Rapid product cadence expands performance and total platform value."]','Extraordinary demand invites extraordinary competition','["Large customers are developing custom accelerators.","Demand is concentrated among a limited number of major buyers.","Export restrictions and supply dependencies can constrain reachable markets."]','If workload economics shift decisively toward alternative accelerators while NVIDIA’s software advantage erodes, current platform expectations would require reassessment.','[{"label":"Q1 FY27 REVENUE","value":"$81.6B · +85%","detail":"Official May 2026 results; judge growth against customer concentration, supply, and the durability of AI infrastructure spending"},{"label":"DATA CENTER","value":"$75.2B · +92%","detail":"Compute, networking, systems, and software adoption remain the dominant value driver"},{"label":"GROSS MARGIN","value":"75.0% non-GAAP","detail":"Track mix, product transitions, export controls, supply costs, and competitive pricing"},{"label":"Q2 FY27 OUTLOOK","value":"$91B ±2%","detail":"Company guidance assumed no Data Center compute revenue from China"},{"label":"OPERATING CASH FLOW","value":"Cash conversion","detail":"Compare customer collections, inventory, supplier prepayments, taxes, and capital expenditures with reported earnings"},{"label":"DILUTED SHARE COUNT","value":"Per-share test","detail":"Measure repurchases against stock compensation, employee issuance, and acquisition consideration"}]','[{"title":"Customer concentration","level":"High","text":"A small group of cloud and technology companies drives substantial infrastructure spending.","signal":"Customer capex and order concentration"},{"title":"Custom silicon","level":"High","text":"Hyperscalers and competitors are investing in alternative accelerators.","signal":"Workload share and relative performance"},{"title":"Export controls","level":"High","text":"Restrictions can limit product configurations and addressable markets.","signal":"New rules and license requirements"},{"title":"Product-transition execution","level":"High","text":"Rapid architecture changes can create qualification delays, inventory exposure, supply imbalance, and customer pauses.","signal":"Launch timing, inventory, purchase commitments, transition costs, and customer deployment schedules"},{"title":"Platform concentration and regulation","level":"Medium","text":"CUDA, networking, acquisitions, and market leadership attract competition and regulatory scrutiny across jurisdictions.","signal":"Competition investigations, licensing remedies, developer adoption, and software attach"}]','[{"title":"Rubin transition and inference economics","text":"Measure time-to-volume, performance per dollar, networking attach, and software monetization rather than relying on benchmark leadership alone.","impact":"BULL CASE"},{"title":"Hyperscaler spending and custom silicon","text":"Separate additive accelerator programs from workloads that permanently move away from NVIDIA''s platform.","impact":"BEAR CASE"},{"title":"Supply and export controls","text":"Track foundry, advanced packaging, memory, optics, system availability, and the revenue pool made inaccessible by regulation.","impact":"NEUTRAL"},{"title":"Per-share cash conversion","text":"Reconcile GAAP earnings, stock compensation, operating cash flow, capex, repurchases, and fully diluted shares.","impact":"NEUTRAL"}]','["What portion of current demand represents recurring production inference rather than one-time capacity buildout?","How much of the platform''s economics comes from networking and software versus accelerators?","Where does custom silicon become a substitute rather than a complement?","Can NVIDIA preserve full-stack returns as customers gain purchasing scale?","What working-capital and supply commitments are required for each architecture transition?","Can software and services become material recurring revenue independent of accelerator cycles?"]','AMD, Intel, hyperscaler custom silicon, Broadcom-enabled ASICs, and specialized AI accelerator companies.','2026-08-01',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',description=excluded.description,lede=excluded.lede,sells=excluded.sells,revenue_model=excluded.revenue_model,opportunity=excluded.opportunity,must_go_right=excluded.must_go_right,editor_note=excluded.editor_note,bull_title=excluded.bull_title,bull_json=excluded.bull_json,bear_title=excluded.bear_title,bear_json=excluded.bear_json,thesis_breaker=excluded.thesis_breaker,financial_drivers_json=excluded.financial_drivers_json,risks_json=excluded.risks_json,monitor_json=excluded.monitor_json,questions_json=excluded.questions_json,competitors=excluded.competitors,evidence_date=excluded.evidence_date,validated_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
